#include <iostream>
using namespace std;

int main() {
    long long n, m;
    cin >> n >> m;

    if (m % n != 0) {
        cout << -1 << '\n';
        return 0;
    }

    long long ratio = m / n;
    int operations = 0;

    while (ratio % 2 == 0) {
        ratio /= 2;
        ++operations;
    }

    while (ratio % 3 == 0) {
        ratio /= 3;
        ++operations;
    }

    cout << (ratio == 1 ? operations : -1) << '\n';
    return 0;
}

